void custom_quicksort(std::vector<double>& arr, int low, int high) {
    if (low < high) {
        int pivot_idx = static_cast<int>(low + (high - low) / 2);
        double pivot = arr[pivot_idx];

        // Move pivot to end
        std::swap(arr[pivot_idx], arr[high]);

        int i = low - 1;
        for (int j = low; j < high; ++j) {
            if (arr[j] <= pivot) {
                ++i;
                std::swap(arr[i], arr[j]);
            }
        }
        std::swap(arr[i + 1], arr[high]);
        int pi = i + 1;

        custom_quicksort(arr, low, pi - 1);
        custom_quicksort(arr, pi + 1, high);
    }
}

